src=pathlib.Path('dev/report-phase2.py').read_text();tree=ast.parse(src);fn=next(x for x in tree.body if isinstance(x,ast.FunctionDef) and x.name=='metrics');exec(compile(ast.Module(body=[fn],type_ignores=[]),'phase2-metrics','exec'))
ref=json.loads((root/'reference-analysis.json').read_text());summary={};rows=['# Hoops Dynasty — Phase 3 competitive-balance investigation','','Baseline production commit: 9d057ddd3af5f6dfb24de35013db440dc34becae. Phase 2 outputs remain intact. Ten independently seeded full regular seasons per league, seeds 101–110; fictional rosters, not verified historical rosters. Changed possession branches change later RNG consumption, so season trajectories are reproducible but not possession-for-possession paired. Controlled fixtures reset state and seed before each game.','']
keys=['points','meanMargin','medianMargin','margin1-5','margin6-10','margin11-19','blow20','blow30','blow40','blow50','homeWin%','fga','fta','orb','totalTov','FG%','3P%','eFG%','TS%','estimatedORtg','MAE','RMSE','signedError','residualSD','OT%','strengthSlope','strengthIntercept','predictedMarginSlope','predictedMarginIntercept','strongerWin%','teamScoreSD','residual40%','meanEnteringQ4Margin','Q4trailerWins%','estimatedPoss','rawPoss','2P%','FT%','3PAshare%']
labels={'points':'Points/team','meanMargin':'Mean winning margin','medianMargin':'Median winning margin','margin1-5':'1–5 point games %','margin6-10':'6–10 point games %','margin11-19':'11–19 point games %','blow20':'20+ margins %','blow30':'30+ margins %','blow40':'40+ margins %','blow50':'50+ margins %','homeWin%':'Home wins %','fga':'FGA/team','fta':'FTA/team','orb':'ORB/team','totalTov':'Total turnovers/team','estimatedORtg':'Points/100 estimated possessions','MAE':'Spread MAE','RMSE':'Spread RMSE','signedError':'Spread signed error','residualSD':'Spread residual SD','OT%':'Overtime games %'}
legacy=json.loads(pathlib.Path('dev/secondary-shot-audit/real-summary.json').read_text())
bench={'nba':{'points':113.83,'meanMargin':12.74,'medianMargin':10,'blow20':21.06,'blow30':6.51,'blow40':1.79,'blow50':.41,'fga':89.2,'fta':21.7,'orb':11.1,'totalTov':14.3,'FG%':46.7,'3P%':36.,'homeWin%':54.39},'wnba':{'points':81.67,'meanMargin':10.82,'medianMargin':9,'blow20':9.17,'blow30':2.92,'blow40':0.,'blow50':0.,'fga':68.3,'fta':18.,'orb':8.2,'totalTov':13.3,'FG%':43.8,'3P%':33.8,'homeWin%':52.5}}
for l,r in legacy.items():bench[l].update({'margin'+k:v for k,v in r['bins'].items()})
for l in ['nba','wnba']:
 raw=json.loads((root/('real-nba-2025.json' if l=='nba' else 'real-wnba-2024.json')).read_text())['resultSets'][0];rs=[dict(zip(raw['headers'],r)) for r in raw['rowSet']];t=lambda k:sum(r[k] for r in rs)
 bench[l].update({'FG%':100*t('FGM')/t('FGA'),'3P%':100*t('FG3M')/t('FG3A'),'2P%':100*(t('FGM')-t('FG3M'))/(t('FGA')-t('FG3A')),'FT%':100*t('FTM')/t('FTA'),'eFG%':100*(t('FGM')+.5*t('FG3M'))/t('FGA'),'TS%':100*t('PTS')/(2*(t('FGA')+.44*t('FTA'))),'estimatedORtg':100*t('PTS')/(t('FGA')-t('OREB')+t('TOV')+.44*t('FTA')),'3PAshare%':100*t('FG3A')/t('FGA')})
 summary[l]={};rows+=['## '+l.upper(),'','| Metric | Phase 2 | Phase 3 | Relative change % | Retained real reference |','|---|---:|---:|---:|---:|']
 for phase in ['phase2','phase3']:
  runs=[json.loads((audit/f'{phase}-{l}-{seed}.json').read_text()) for seed in range(101,111)];assert all(len(r['games'])==(1230 if l=='nba' else 240) for r in runs)
  gs=[g for r in runs for g in r['games']];summary[l][phase]={'aggregate':metrics(gs),'bySeed':[metrics(r['games']) for r in runs]}
 a=summary[l]['phase2']['aggregate'];b=summary[l]['phase3']['aggregate']
 for k in keys:
  av=a.get(k);bv=b.get(k);change=100*(bv-av)/av if av else None;fmt=lambda x:'Unavailable' if x is None else f'{x:.2f}'
  rows.append(f'| {labels.get(k,k)} | {fmt(av)} | {fmt(bv)} | {fmt(change)} | {fmt(bench[l].get(k))} |')
 rows+=['','Rate rows are percentages; relative change is not percentage-point change. Estimated possessions = FGA − ORB + total TOV + 0.44 FTA, not official pace. The shot-type foul correction changes the FT mix, so this generic estimator remains approximate.','', '| Metric | Revised seed mean | Approx. 95% interval | Seed range |','|---|---:|---:|---:|']
 for k in ['points','meanMargin','blow20','blow30','blow40','blow50']:
  vals=[m[k] for m in summary[l]['phase3']['bySeed']];m=st.mean(vals);h=2.262*st.stdev(vals)/math.sqrt(10);rows.append(f'| {labels.get(k,k)} | {m:.2f} | {max(0,m-h):.2f}–{m+h:.2f} | {min(vals):.2f}–{max(vals):.2f} |')
 rows+=['','Intervals use ten season seeds, not independent-game assumptions. Rare blowout tails remain uncertain.','']
 gs=[g for seed in range(101,111) for g in json.loads((audit/f'phase3-{l}-{seed}.json').read_text())['games']]
 rows+=['### Pregame calibration','','| Predicted home margin | Games | Actual home margin | MAE | RMSE |','|---|---:|---:|---:|---:|']
 for lo,hi in [(-100,-10),(-10,-5),(-5,0),(0,5),(5,10),(10,100)]:
  xs=[g for g in gs if lo<=-g['spread']<hi]
  if xs:
   m=metrics(xs);rows.append(f"| {lo} to {hi} | {len(xs)} | {st.mean(g['score'][0]-g['score'][1] for g in xs):.2f} | {m['MAE']:.2f} | {m['RMSE']:.2f} |")
 rows+=['','| Strength gap | Games | Mean margin | 30+ % | 40+ % |','|---|---:|---:|---:|---:|']
 for lo,hi in [(0,2),(2,5),(5,10),(10,100)]:
  xs=[g for g in gs if lo<=abs(g['strengths'][0]-g['strengths'][1])<hi]
  if xs:
   m=metrics(xs);rows.append(f"| {lo}–{hi} | {len(xs)} | {m['meanMargin']:.2f} | {m['blow30']:.2f} | {m['blow40']:.2f} |")
 rows+=['']
rows+=['## Findings and implemented corrections','',
'1. Confirmed shot-type foul defect: the primary shooting-foul hazard was independent of whether the attempt was worth two or three points. Phase 2 recorded 245 NBA and 205 WNBA three-shot trips in 50 diagnostic games per league. Forty evenly spaced official regular-season play-by-play samples (20 per league) contained 14 and 10 three-shot shooting fouls. All sampled final scores were checked against the official league game logs. The samples establish a large mismatch, not exact universal rates for every era.',
'2. Confirmed defender-state defect: switches/help changes updated the defender object but could retain the previous defender’s fatigue progress. A forced-switch test reproduced 117 mismatched attribute evaluations out of 1,373; the candidate had zero mismatches in 1,348 evaluations. The new accessor reads the currently assigned defender’s stamina. Different branch outcomes explain the different call counts.',
'3. Modern foul calibration: shooting-contact multipliers are 0.12 for threes, 1.8 for NBA twos and 1.6 for WNBA twos. Conditional completion multipliers for fouled attempts are 0.45 and 0.35, replacing 0.70; normal field-goal accuracy is unchanged. These are explicit model translations informed by the sampled two-/three-shot and and-one mix, not measured physiological or annual league constants. Existing player foul tendencies, defensive IQ, draw-foul behavior, coaching discipline, crowd and league foul sliders still operate. Only start years 2023 onward use these priors; earlier seasons retain their prior foul calibration. Historical statistical calibration is not claimed.',
'4. Ratings were not compressed. The direct shooting matchup curve changes one percentage point per five rating points. Defensive ratings change it in the opposite direction. IQ, ball security, blocking and rebounding have separate bounded effects. Isolation has discrete advantage thresholds and physical caps/three-point low-rating behavior are nonlinear; the ablations do not establish these as the dominant source of excessive tails.',
'5. The pregame strength metric is 80% first-five OVR average plus 20% remaining-roster OVR average. It is not minutes-, injury-, fatigue-, attribute-, position- or tactic-aware. Therefore a 0–2 strength gap is not an independently validated equal-quality matchup. Its slope cannot by itself prove attribute scaling is excessive. No spread widening was used.',
'6. Physical build changes derived mobility, strength, reach and endurance; direct mismatch adjustments are also present. The direct mismatch probabilities are bounded. Neutralizing physical effects is a diagnostic, not a proposed removal of height/strength advantages. Runtime attributes are restored after each game.',
'7. Fatigue and rotation effects are real but their ablations do not justify blaming fatigue alone. A shallow bench changes actual lineup quality, which the simple strength metric underweights. Garbage-time rotations and score-conditioned bins are reported separately; correlation with a lead is not proof of a feedback bug.',
'8. Crowd advantages include home accuracy, road pressure, fouls, turnovers and small rebounding effects; separate two-rest-day home bonuses and rivalry effects also exist. Neutral fixtures remove crowd, rivalry, altitude difference and rest asymmetry. Existing production home-court settings were not retuned from a single reference season.',
'9. No shared game-level shooting multiplier was found in the inspected shot path. Shots use independent random draws plus contextual probabilities. Isolation heat and home momentum are bounded, not unbounded lead-based bonuses. No comeback logic, score caps, predetermined margins or hidden score edits were introduced.','']
rows+=['## Official shooting distributions','','Official league game logs contain 2,460 NBA and 480 WNBA team-game rows. The old real margin benchmark is retained for continuity. The newly retrieved NBA logs yield mean margin 12.748 and scoring 113.825, a small source/revision discrepancy from the retained 12.740/113.827; it does not explain the simulation gap. WNBA totals agree.','', '| League / statistic | Real mean % | Real SD | Real p10 | Real p90 |','|---|---:|---:|---:|---:|']
for l,r in ref.items():
 for k,v in r['metrics'].items():rows.append(f"| {l} / {k} | {v['mean']:.2f} | {v['sd']:.2f} | {v['p10']:.2f} | {v['p90']:.2f} |")
rows+=['','The NBA Phase 2 FG% p10–p90 of 41.94–56.10 is primarily shifted upward relative to the real 39.80–53.75 range. The WNBA Phase 2 range is 37.84–53.09 versus real 36.76–50.82. This does not support indiscriminately suppressing shot randomness. Opponents’ scores are more positively correlated in the real logs; fixed clock slots and limited shared pace variation remain possible contributors, not proven causes.', '', 'Phase 2 free-throw-made difference SD was approximately 8.88 NBA / 8.25 WNBA, compared with 7.15 / 6.48 in the official logs. This motivated the foul-path investigation; correcting foul-type frequencies does not by itself guarantee the entire margin distribution is fixed.','']
rows+=['## Controlled ablations','','Each case uses 200 reset games and seeds 80000–80199, with four roster fixtures (50 games each). Both sides have the same stored physical biography in identical-roster tests; changing IDs must not regenerate different bodies. Coaches are initialized before fixture capture. Exploratory runs that did not guarantee these conditions are retained separately and excluded here. Population cases use four fixed unequal roster pairings and are sensitivity tests, not league-wide estimates. The no-coach case neutralizes skill/fit contributions, not every tactical behavior. The no-fatigue case removes effective-attribute fatigue only; stamina-driven substitutions remain.','', '| League / case | Games | Home margin | Mean absolute margin | Margin SD | 20+ % | 30+ % | 40+ % | Home wins % |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
assert len([f for f in root.glob('baseline-*.json') if f.name!='baseline-hashes.json'])==48,'Incomplete ablations'
for f in sorted(root.glob('baseline-*.json')):
 if f.name=='baseline-hashes.json':continue
 r=json.loads(f.read_text());assert r['count']==200
 if not r['scenario'].startswith('population'):assert r.get('fixtureVersion')==3,f
 m=[g['score'][0]-g['score'][1] for g in r['games']];rows.append(f"| {r['league']} / {r['scenario']} | {len(m)} | {st.mean(m):.2f} | {st.mean(map(abs,m)):.2f} | {st.pstdev(m):.2f} | {100*st.mean(abs(x)>=20 for x in m):.2f} | {100*st.mean(abs(x)>=30 for x in m):.2f} | {100*st.mean(abs(x)>=40 for x in m):.2f} | {100*st.mean(x>0 for x in m):.2f} |")
rows+=['','Four fixture clusters and 200 games per case leave substantial uncertainty; changes in RNG branches prevent shot-for-shot pairing. A small difference is not treated as proof of causation.','']
rows+=['## Attribute sweeps','','Eight direct-calculation ratings: 60, 65, 70, 75, 80, 85, 90, 95. The retained JSON includes shooting and defense, free throws, handling/steal/isolation risk, blocking, IQ, endurance and rebound weights plus a height/weight grid. These are calculation sweeps, not independent full-game trials for every individual attribute. Passing and rotation interactions are additionally inspected in code and controlled team tests.','', '| Rating | Inside vs 75 | Midrange vs 75 | Three vs 75 | FT | Inside 75 vs defense | Handling TO before context |','|---|---:|---:|---:|---:|---:|---:|']
for r in json.loads((root/'attribute-curves.json').read_text())['rows']:rows.append('| '+str(r['rating'])+' | '+' | '.join(f"{100*r[k]:.2f}%" for k in ['insideAttack','midAttack','threeAttack','freeThrow','insideDefense','handlingTurnover'])+' |')
rows+=['','## Historical formats and persistence','','Historical tests use 30 full-length games each for NBA 1997/2025 and WNBA 1997/2006/2024. Fictional six-team fixtures check rules and score/box/event consistency, not historical statistical calibration. Results are in dev/phase3/historical.json. Existing shot-clock, period, overtime and altitude mechanics are preserved. No save-schema migration or permanent attribute changes are introduced.','', 'Completed game records and city photographs are preserved. Full-season checks enforce game counts, minutes, shooting bounds, score/box/period agreement and baseline hashes. The regression log records save/load, feats, fouls and secondary fatigue checks. Browser visual/device QA is not part of this engine-only audit.','', '## Remaining limitations','','The fixed-window possession engine remains an approximation. Secondary shots do not have all primary foul/turnover paths. Sparse historical priors are not verified annual calibrations. Modern foul parameters use a limited 40-game PBP sample. Home advantage, roster/rotation quality representation and pregame predictions still need improvement if the final metrics remain outside credible ranges. Lower scoring alone is not accepted as competitive-balance success.','', '## Files and reproduction','','Production changes: dist/attributes.js and dist/index.html (cache key). Audit code and retained results: dev/phase3-*.cjs, dev/run-phase3-*.cjs, dev/phase3-*.py, dev/report-phase3.py, dev/phase3/, dev/balance-audit/phase3-*.json, and the optional-transform hook in dev/audit-competitiveness.cjs. Phase 2 results are not overwritten.','', 'Full-season runner: node dev/run-phase3-seasons.cjs. Controlled runners: node dev/run-phase3-diagnostics.cjs and node dev/run-phase3-population.cjs. Read retained outputs rather than silently resimulating an existing seed. The candidate transform and its manifest identify the tested calculation changes.','', '## Sources','','Official complete team game logs: https://stats.nba.com/stats/leaguegamelog (LeagueID=00, Season=2024-25, PlayerOrTeam=T, SeasonType=Regular Season) and https://stats.wnba.com/stats/leaguegamelog (LeagueID=10, Season=2024). Raw responses retained under dev/phase3/real-*.json.','', 'Official play-by-play: https://cdn.nba.com/static/json/liveData/playbyplay/ and https://cdn.wnba.com/static/json/liveData/playbyplay/. Exact URLs, sampled game IDs, download outcomes and score verification are retained in reference-fetch.json and reference-analysis.json. Samples are evenly spaced over sorted regular-season game IDs; this is a coverage sample, not a claim of random sampling.','', 'Phase 2 reference data and sources remain in docs/PHASE2-COMPETITIVENESS.md.']
(root/'summary.json').write_text(json.dumps(summary,indent=2));pathlib.Path('docs/PHASE3-COMPETITIVENESS.md').write_text('\n'.join(rows)+'\n');print('Wrote complete Phase 3 report')
